function bindPipelineBridge(){if(state.pipelineBridgeBound)return;state.pipelineBridgeBound=true;document.addEventListener('click',function(event){var btn=event.target.closest('button');if(!btn||!/compare/i.test(btn.textContent.trim()))return;var root=document.getElementById('scoutExperienceApp');if(!root)return;var ids=[];qa(root,'input[type="checkbox"]:checked').forEach(function(input){var row=input.closest('[data-player-id],[data-player],[data-pipeline-player-id],tr,.pipeline-card'),id=input.value||row&& (row.dataset.playerId||row.dataset.player||row.dataset.pipelinePlayerId);if(id)ids.push(id)});if(ids.length<2){qa(root,'[data-player-id]').slice(0,2).forEach(function(node){if(node.dataset.playerId)ids.push(node.dataset.playerId)})}ids=Array.from(new Set(ids)).slice(0,2);if(ids.length<2)return toast('Choose two pipeline players before comparing them.',true);event.preventDefault();event.stopImmediatePropagation();location.href='/scout/compare-players?player='+encodeURIComponent(ids[0])+'&playerB='+encodeURIComponent(ids[1])},true)}

