function enhancePipelinePage(){var root=document.getElementById('scoutExperienceApp');if(!root)return;qa(root,'button').forEach(function(btn){var label=btn.textContent.trim();if(label==='Pipeline settings')btn.remove();if(label==='Export pipeline')btn.onclick=async function(){var done=pending(btn,'Exporting…');try{var response=await request('POST','/api/exports/pipeline',{format:'Excel'});downloadBase64(response.filename,response.mime,response.contentBase64);toast('Pipeline exported with compatibility and counted as one export.')}catch(error){toast(error.message,true)}finally{done()}}})}

function hydrateRoute(root,overview){if(state.route==='dashboard')hydrateDashboard(root,overview);else if(state.route==='search')bindSearch(root);else if(state.route==='profile'){if(state.profile)hydrateProfile(root,state.profile);else loadProfile().then(function(bundle){state.profile=bundle;hydrateProfile(root,bundle)}).catch(function(e){toast(e.message,true)})}else if(state.route==='rankings')bindRankings(root);else if(state.route==='fixtures')bindFixtures(root);else if(state.route==='predictions')bindPredictions(root,overview);else if(state.route==='exports')bindExports(root,overview);else if(state.route==='compare')bindCompare(root,overview);else if(state.route==='setup')bindSetup(root);else if(state.route==='chat')bindChat(root);else if(state.route==='notifications')bindNotifications(root);else if(state.route==='settings')bindSettings(root,overview)}
async function init(){state.route=routeId();if(state.route==='pipeline'){bindPipelineBridge();setTimeout(enhancePipelinePage,50);setTimeout(enhancePipelinePage,600);return}if(!templates[state.route])return;waitForWorkspace(async function(app,content){content.innerHTML=loadingMarkup(state.route);app.classList.add('is-loading');try{await loadPlayers();var overviewPromise=loadOverview(),profilePromise=state.route==='profile'?loadProfile():Promise.resolve(null),values=await Promise.all([overviewPromise,profilePromise]);var overview=values[0];state.profile=values[1];var root=mount(content);app.classList.remove('is-loading');hydrateRoute(root,overview)}catch(e){app.classList.remove('is-loading');content.innerHTML='<div class="slv6-approved"><div class="empty structured"><b>ScoutLink could not load</b><span>'+esc(e.message)+'</span><button class="btn primary" type="button" onclick="location.reload()">Try again</button></div></div>'}})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
